 public static object Run(){if(!EditorApplication.isPlaying)return "NOT PLAYING";camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.name=="Camera");oldPosition=camera.transform.position;oldRotation=camera.transform.rotation;movement=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).FirstOrDefault(m=>m&&m.GetType().Name=="KarakterHareket");oldMovement=movement&&movement.enabled;if(movement)movement.enabled=false;manager=UnityEngine.Object.FindFirstObjectByType<SceneOptimizationController>();ready=manager.occlusionReady;groups=UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None).Where(g=>g.transform.Find("Station distance LOD1")).ToArray();if(groups.Length!=95)throw new Exception("Expected95 new LOD groups");renderers=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.gameObject.layer!=LayerMask.NameToLayer("DistantMountains")&&r.bounds.SqrDistance(new Vector3(460,3,905))<10000&&!r.sharedMaterials.Any(m=>m&&m.shader&&(m.shader.name.IndexOf("Grass",StringComparison.OrdinalIgnoreCase)>=0||m.shader.name.IndexOf("Tree",StringComparison.OrdinalIgnoreCase)>=0))).ToArray();gpuAllowed=renderers.Select(r=>(bool)GpuDriven.GetValue(r)).ToArray();var cs=UnityEngine.Object.FindObjectsByType<StationShadowCaster>(FindObjectsSortMode.None).Where(c=>c.enabled&&c.SourceRenderer).ToArray();shadowFilters=cs.Select(c=>c.GetComponent<MeshFilter>()).ToArray();oldShadowMeshes=shadowFilters.Select(f=>f.sharedMesh).ToArray();lightShadowMeshes=cs.Select(c=>{var m=c.SourceRenderer.GetComponent<MeshFilter>().sharedMesh;string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m,out guid,out id);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Optimization/StationDistanceLODs/"+guid+"_"+id+"_medium.asset");if(!mesh)throw new Exception("Missing shadow candidate");return mesh;}).ToArray();rate=Application.targetFrameRate;vsync=QualitySettings.vSyncCount;background=A