 static void Restore(){for(int i=0;i<shadowFilters.Length;i++)if(shadowFilters[i])shadowFilters[i].sharedMesh=oldShadowMeshes[i];manager.occlusionReady=ready;camera.useOcclusionCulling=ready;foreach(var g in groups)if(g)g.ForceLOD(-1);for(int i=0;i<renderers.Length;i++)if(renderers[i])GpuDriven.SetValue(renderers[i],gpuAllowed[i]);}
