 static void Next(){Restore();phase++;if(phase>=views.Length*modes.Length){Finish();return;}int view=phase/modes.Length;camera.transform.SetPositionAndRotation(views[view],Quaternion.Euler(0,yaw[view],0));string mode=modes[phase%modes.Length];bool before=mode.StartsWith("Before"),native=mode=="NativeOnly"||mode.StartsWith("Combined")||mode.StartsWith("Optimized"),lod=!before&&mode!="NativeOnly";manager.occlusionReady=native;camera.useOcclusionCulling=native;foreach(var g in groups)g.ForceLOD(lod?-1:0);if(mode=="CombinedCPU")foreach(var r in renderers)GpuDriven.SetValue(r,false);if(mode.StartsWith("Optimized"))for(int i=0;i<shadowFilters.Length;i++)shadowFilters[i].sharedMesh=lightShadowMeshes[i];times.Clear();gpuTimes.Clear();triangles=batches=0;start=EditorApplication.timeSinceStartup;ScreenCapture.CaptureScreenshot(Path.GetFullPath("Library/StationShadowGeometry_"+view+"_"+mode+".png"));File.WriteAllText("Library/StationShadowGeometryBenchmark.status",view+" "+mode);}
